INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(38661, 'Job 36:15', 'Job', 36, 15, 'خو هغه مظلومان د ظلم نه بچ کوى، او د مصيبتونو په وخت کښې ورته خپل ځان څرګندوى.', 'خو هغه مظلومان د ظلم نه بچ کوی، او د مصیبتونو په وخت کشې ورته خپل جان چرګندوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_36_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38662, 'Job 36:16', 'Job', 36, 16, 'ايُوبه، خُدائ پاک دې تا د خطرې نه وباسى، او هغه ځائ ته دې بوځى چرته چې غم نۀ وى. هغه ستا په دسترخوان باندې ښۀ ښۀ خوراکونه کېښودل.', 'ایوبه، خدای پاک دې تا د خطرې نه وباسی، او هغه جای ته دې بوجی چرته چې غم نۀ وی. هغه ستا په دسترخوان باندې شۀ شۀ خوراکونه کېشودل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_36_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38663, 'Job 36:17', 'Job', 36, 17, 'خو د نورو بدعملو په شان به پوره سزا تا ته ملاويږى، تۀ په عدالت او اِنصاف کښې راګېر يې.', 'خو د نورو بدعملو په شان به پوره سزا تا ته ملاویزی، تۀ په عدالت او انصاف کشې راګېر یې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_36_17.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237840, 1761237840),
(38664, 'Job 36:18', 'Job', 36, 18, 'خبردار چې رشوت دې دوکه نۀ کړى، او دولت دې بې‌لارې نۀ کړى.', 'خبردار چې رشوت دې دوکه نۀ کری، او دولت دې بې‌لارې نۀ کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_36_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38665, 'Job 36:19', 'Job', 36, 19, 'ستا دولت او ستا طاقت ټول به تا د تکليف نه بچ کړى څۀ؟', 'ستا دولت او ستا طاقت تول به تا د تکلیف نه بچ کری چۀ؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_36_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38666, 'Job 36:20', 'Job', 36, 20, 'د شپې د راتلو خواهش مۀ کوه، د هغه وخت چې کله قومونه تباه کيږى.', 'د شپې د راتلو خواهش مۀ کوه، د هغه وخت چې کله قومونه تباه کیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_36_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38667, 'Job 36:21', 'Job', 36, 21, 'خبردار، چې د بدعملۍ طرف ته وانۀ وړې، خُدائ پاک ځکه په تکليف کړے يې چې په بدعملۍ کښې آخته نۀ شې.', 'خبردار، چې د بدعملی طرف ته وانۀ ورې، خدای پاک جکه په تکلیف کرے یې چې په بدعملی کشې اخته نۀ شې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_36_21.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237840, 1761237840),
(38668, 'Job 36:22', 'Job', 36, 22, 'ياد ساته چې د خُدائ پاک طاقت څومره لوئ دے، او هغه د ټولو نه عظيم اُستاذ دے.', 'یاد ساته چې د خدای پاک طاقت چومره لوی دے، او هغه د تولو نه عظیم استاذ دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_36_22.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237840, 1761237840),
(38669, 'Job 36:23', 'Job', 36, 23, 'هيڅوک خُدائ پاک ته دا نۀ شى وئيلے چې هغه به څۀ کوى، او څوک ورته وئيلے شى چې تا غلط کار کړے دے؟', 'هیچوک خدای پاک ته دا نۀ شی وییلے چې هغه به چۀ کوی، او چوک ورته وییلے شی چې تا غلط کار کرے دے؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_36_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38670, 'Job 36:24', 'Job', 36, 24, 'څۀ چې هغه کوى په هغې تل د هغۀ تعريف کيږى. تۀ هم د هغۀ ثناء صِفت کوه.', 'چۀ چې هغه کوی په هغې تل د هغۀ تعریف کیزی. تۀ هم د هغۀ ثناء صفت کوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_36_24.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237840, 1761237840),
(38671, 'Job 36:25', 'Job', 36, 25, 'ټولو خلقو دې ته کتلى دى، هر يو کس د لرې نه دې ته ګورى.', 'تولو خلقو دې ته کتلی دی، هر یو کس د لرې نه دې ته ګوری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_36_25.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237840, 1761237840),
(38672, 'Job 36:26', 'Job', 36, 26, 'بې‌شکه خُدائ پاک لوئ دے او مونږ د هغۀ د لويئ اندازه هم نۀ شُو لګولے، د هغۀ د کالونو شمېر نشته.', 'بې‌شکه خدای پاک لوی دے او مونز د هغۀ د لویی اندازه هم نۀ شو لګولے، د هغۀ د کالونو شمېر نشته.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_36_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38673, 'Job 36:27', 'Job', 36, 27, 'ځکه چې هغه نمى اوچتوى، او په باران يې بدلوى،', 'جکه چې هغه نمی اوچتوی، او په باران یې بدلوی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_36_27.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237840, 1761237840),
(38674, 'Job 36:28', 'Job', 36, 28, 'هغه وريځې جوړوى او په هر چا باران راوروى.', 'هغه وریجې جوروی او په هر چا باران راوروی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_36_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38675, 'Job 36:29', 'Job', 36, 29, 'څوک د وريځو په خورېدو باندې پوهيږى، او د آسمان په تندر باندې پوهيږى څۀ؟', 'چوک د وریجو په خورېدو باندې پوهیزی، او د اسمان په تندر باندې پوهیزی چۀ؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_36_29.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38676, 'Job 36:30', 'Job', 36, 30, 'ګوره، هغه په آسمان کښې برېښنا راولى خو د سمندر بېخ کښې تيارۀ وى.', 'ګوره، هغه په اسمان کشې برېشنا راولی خو د سمندر بېخ کشې تیارۀ وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_36_30.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38677, 'Job 36:31', 'Job', 36, 31, 'ځکه چې د دې په ذريعه هغه په خلقو حکومت کوى، او هغه خلقو له بې‌حسابه خوراک ورکوى.', 'جکه چې د دې په ذریعه هغه په خلقو حکومت کوی، او هغه خلقو له بې‌حسابه خوراک ورکوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_36_31.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38678, 'Job 36:32', 'Job', 36, 32, 'هغه برېښنا په خپلو لاسونو کښې ساتى، او حُکم ورکوى چې نښه وولى.', 'هغه برېشنا په خپلو لاسونو کشې ساتی، او حکم ورکوی چې نشه وولی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_36_32.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38679, 'Job 36:33', 'Job', 36, 33, 'د هغۀ د تندر آواز داسې وائى، چې هغه غېرتى دے او د ګناه خِلاف غصه لرى.', 'د هغۀ د تندر اواز داسې وایی، چې هغه غېرتی دے او د ګناه خلاف غصه لری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_36_33.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38680, 'Psalms 99:1', 'Psalms', 99, 1, 'پاچاهي کوي څښتن نو ودې لړزیږي د دنیا قومونه هغه دی ناست په تخت د اسماني مخلوق دپاسه نو ځمکه دې شي په لړزېدلو باندې', 'پاچاهی کوی چشتن نو ودې لرزیزی د دنیا قومونه هغه دی ناست په تخت د اسمانی مخلوق دپاسه نو جمکه دې شی په لرزېدلو باندې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_99_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38681, 'Psalms 99:2', 'Psalms', 99, 2, 'څښتن لویي څرګندوي صهیون کې او دی اوچت په ټولو ولسونو باندې', 'چشتن لویی چرګندوی صهیون کې او دی اوچت په تولو ولسونو باندې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_99_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38682, 'Psalms 99:3', 'Psalms', 99, 3, 'هغوی دې ووایي ثنا د هغه د لوی او هیبتناکه نامه ځکه چې دی هغه سپېڅلی', 'هغوی دې ووایی ثنا د هغه د لوی او هیبتناکه نامه جکه چې دی هغه سپېچلی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_99_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38683, 'Psalms 99:4', 'Psalms', 99, 4, 'ای ځواکمن پاچا، مینه لرې د عدالت سره ته تا قایم کړلو انصاف په اسراییلو کې دې کړی عدالت او نېکي', 'ای جواکمن پاچا، مینه لرې د عدالت سره ته تا قایم کرلو انصاف په اسراییلو کې دې کری عدالت او نېکی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_99_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38684, 'Psalms 99:5', 'Psalms', 99, 5, 'ثنا او صفت وکړئ زمونږ د څښتن خدای د تخت په مخکې یې د پښو په چوکۍ وکړئ سجده ځکه چې دی هغه سپېڅلی', 'ثنا او صفت وکری زمونز د چشتن خدای د تخت په مخکې یې د پشو په چوکی وکری سجده جکه چې دی هغه سپېچلی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_99_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38685, 'Psalms 99:6', 'Psalms', 99, 6, 'موسی او هارون وو د هغه کاهنان او سموییل هم د هغې ډلې ؤ چې نوم یې د څښتن یاداوه څښتن ته یې وکړلو فریاد او هغه قبول یې کړ سوال', 'موسی او هارون وو د هغه کاهنان او سموییل هم د هغې دلې و چې نوم یې د چشتن یاداوه چشتن ته یې وکرلو فریاد او هغه قبول یې کر سوال', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_99_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38686, 'Psalms 99:7', 'Psalms', 99, 7, 'د ورېځ له منځه یې له دوی سره خبرې وکړې هغوی ومنل احکام او قوانین د هغه چې یې ورکړي وو هغوی ته', 'د ورېج له منجه یې له دوی سره خبرې وکرې هغوی ومنل احکام او قوانین د هغه چې یې ورکری وو هغوی ته', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_99_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38687, 'Psalms 99:8', 'Psalms', 99, 8, 'ای څښتنه! ای زمونږه خدایه! تا کړ قبول د خپلو خلکو سوال ته د هغوی بخښونکی خدای وې سره له دې چې تا د دوی د ګناهونو سزا ورکړه دوی ته', 'ای چشتنه! ای زمونزه خدایه! تا کر قبول د خپلو خلکو سوال ته د هغوی بخشونکی خدای وې سره له دې چې تا د دوی د ګناهونو سزا ورکره دوی ته', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_99_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38688, 'Psalms 99:9', 'Psalms', 99, 9, 'زمونږ د څښتن خدای ثنا او صفت وکړئ عبادت وکړئ د هغه په سپېڅلي غره باندې ځکه سپېڅلی دی زمونږ څښتن خدای', 'زمونز د چشتن خدای ثنا او صفت وکری عبادت وکری د هغه په سپېچلی غره باندې جکه سپېچلی دی زمونز چشتن خدای', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_99_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38689, 'Psalms 8:1', 'Psalms', 8, 1, 'ای څښتنه، زمونږ باداره! په ټول جهان کې د ستا نوم لوی دی ستا ثنا او صفت رسیږي تر اسمانه', 'ای چشتنه، زمونز باداره! په تول جهان کې د ستا نوم لوی دی ستا ثنا او صفت رسیزی تر اسمانه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_8_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38690, 'Psalms 8:2', 'Psalms', 8, 2, 'ماشومان او تي رودونکي ماشومان ستا د لویۍ سندرې وایي تا جوړه کړې ده قوي کلا د خپلو دښمنانو په ضد هم په خپله چوپ کوې مخالفان خپل', 'ماشومان او تی رودونکی ماشومان ستا د لویی سندرې وایی تا جوره کرې ده قوی کلا د خپلو دشمنانو په ضد هم په خپله چوپ کوې مخالفان خپل', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_8_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38691, 'Psalms 8:3', 'Psalms', 8, 3, 'کله چې وګورم اسمان ته چې جوړ کړی دی تا ستوري سپوږمۍ ته چې ځای په ځای کړي دي تا', 'کله چې وګورم اسمان ته چې جور کری دی تا ستوری سپوزمی ته چې جای په جای کری دی تا', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_8_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38692, 'Psalms 8:4', 'Psalms', 8, 4, 'نو انسان څه دی چې ته یې خیال ساتې؟ فاني انسان چې ته پرې پام ساتې؟', 'نو انسان چه دی چې ته یې خیال ساتې؟ فانی انسان چې ته پرې پام ساتې؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_8_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
